from solution import collapse_balances

rows = [('cash', 3), ('debt', -2), ('cash', 4), ('debt', 2)]
assert collapse_balances(rows) == {'cash': 7, 'debt': 0}
assert rows == [('cash', 3), ('debt', -2), ('cash', 4), ('debt', 2)]
assert collapse_balances([]) == {}

from solution import bounded_ratio

assert bounded_ratio(3, 2) == 1.5
assert bounded_ratio(-3, 2) == -1.5
for denominator in (0, -1):
    try:
        bounded_ratio(1, denominator)
    except ValueError:
        pass
    else:
        raise AssertionError('expected ValueError')

from solution import parse_positive_ints

assert parse_positive_ints([' 3 ', '', '7']) == [3, 7]
for values in (['0'], ['-2'], ['x']):
    try:
        parse_positive_ints(values)
    except ValueError:
        pass
    else:
        raise AssertionError('expected ValueError')

from solution import merge_known_preferences

defaults = {'theme': 'light', 'locale': 'en'}
overrides = {'theme': 'dark', 'extra': 'ignored'}
assert merge_known_preferences(defaults, overrides) == {'theme': 'dark', 'locale': 'en'}
assert defaults == {'theme': 'light', 'locale': 'en'}
assert overrides == {'theme': 'dark', 'extra': 'ignored'}

from solution import invoice_total

assert invoice_total([{'status': 'OPEN', 'amount': 4}, {'status': 'PAID', 'amount': 99}, {'status': 'OPEN', 'amount': -1}]) == 3
try:
    invoice_total([{'status': 'OPEN', 'amount': '4'}])
except ValueError:
    pass
else:
    raise AssertionError('expected ValueError')

from solution import window_maximums

assert window_maximums([1, 3, 2, 5, 4], 3) == [3, 5, 5]
assert window_maximums([7], 1) == [7]
for width in (0, 2):
    try:
        window_maximums([7], width)
    except ValueError:
        pass
    else:
        raise AssertionError('expected ValueError')
